// Lookup returns the file with the given name.
// It returns (f, true) if such a file is found, and (nil, false) otherwise.
func (a *Archive) Lookup(name string) (*File, bool) {
	for i := range a.Files {
		if a.Files[i].Name == name {
			return &a.Files[i], true
		}
	}
	return nil, false
}
